async function callMcpTool(options, params) {
  const { url, apiKey, timeoutMs = 3e4 } = options;
  const body = {
    jsonrpc: "2.0",
    id: Date.now(),
    method: "tools/call",
    params: {
      name: params.name,
      arguments: params.arguments
    }
  };
  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`
    },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(timeoutMs)
  });
  if (!response.ok) {
    throw new Error(`MCP HTTP ${response.status}: ${(await response.text()).slice(0, 200)}`);
  }
  const data2 = await response.json();
  if (data2.error) {
    throw new Error(data2.error.message || "MCP tool call failed");
  }
  const textContent = data2.result?.content?.find((c) => c.type === "text")?.text;
  if (textContent) {
    try {
      return JSON.parse(textContent);
    } catch {
      return textContent;
    }
  }
  return data2.result ?? null;
}
